  insert into public.learning_skill_lessons(
    canonical_skill_id, version, title, summary, content_markdown,
    worked_example, tips, estimated_minutes, active, metadata
  ) values (
    v_skill_id, 5, 'Uma cadeia produtiva distribui etapas, benefícios e custos', 'Um produto passa por etapas e por diferentes agentes. Para avaliar impactos, compare indicadores com unidade, período e escala, observe quem recebe benefícios e quem suporta custos e não conclua além do que os dados mostram.', '## Comece pela cadeia, não por um rótulo
Uma cadeia produtiva pode incluir obtenção de recursos, cultivo ou extração, processamento, transporte, venda, uso e descarte. As etapas variam conforme o produto. Identificar agentes e relações ajuda a perguntar onde uma mudança ocorreu e quem foi afetado. Um diagrama é uma hipótese de organização; fontes e pessoas envolvidas podem mostrar etapas que ficaram de fora.

## Compare indicadores com cuidado
Preço, renda e postos de trabalho são dimensões econômicas. Uso de água, mudança de cobertura do solo, resíduos e condições de trabalho dizem respeito a dimensões socioambientais distintas. Não existe um único número que resuma todas elas. Antes de comparar, confira o que foi medido, a unidade, o período, a área, o denominador e a origem. “Por unidade produzida” não é o mesmo que “total”: a eficiência pode melhorar enquanto a escala aumenta.

## Mude a escala e pergunte quem ganha e quem arca
Um indicador local pode esconder diferenças entre propriedades, trabalhadores, consumidores e comunidades. Uma média regional não descreve cada lugar. Observe a distribuição e o modo de vida das populações envolvidas, mas não atribua uma experiência a uma comunidade real sem fontes situadas e mediação. Quando o cenário for inventado para estudo, ele deve ser identificado como simulação.

## Evidência não é causalidade automática
Dois números que mudam juntos não provam que um causou o outro. Compare períodos e métodos, procure explicações alternativas e registre lacunas. Fontes produzidas por empresas, governos, organizações ou pesquisadores podem responder perguntas diferentes; autoria não decide sozinha se um dado é válido. Triangule afirmações importantes e declare o grau de certeza possível.

## Avalie alternativas por critérios explícitos
Uma proposta pode reduzir um impacto e aumentar outro, distribuir custos de modo desigual ou depender de condições ainda não verificadas. Defina critérios, compare quem é afetado em cada escala e explique o que ainda precisa ser medido. Uma boa avaliação apresenta benefícios, custos, incertezas e alternativas sem transformar uma dimensão em solução universal.',
    'Exemplo inteiramente fictício: uma cooperativa compara dois processos para embalar a mesma quantidade de alimento durante um mês. O processo A usa 12 unidades de água por lote e gera 8 unidades de resíduo; o B usa 9 e gera 13. O quadro não informa energia, custo, destino do resíduo nem distribuição entre fornecedores. É possível dizer que B tem menor uso de água nesse indicador e maior resíduo no período; não é possível chamá-lo de melhor em todos os aspectos. O próximo passo é explicitar prioridades, verificar unidades e buscar os dados ausentes.', array['Desenhe etapas e agentes antes de julgar o impacto.', 'Anote unidade, período, escala e denominador de cada indicador.', 'Separe o que o dado mostra do que ainda é hipótese.', 'Pergunte quem recebe benefícios, quem suporta custos e quais vozes faltam.', 'Compare alternativas por mais de um critério e declare incertezas.']::text[], 24, false, '{"content_pack":"TECESCOLA_CORE_V5_QUESTION_FIRST","content_id":"v5-humanities-production-impacts","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","publication_status":"STAGING","bncc_alignment_status":"NOT_CLAIMED","prior_knowledge":["Ler tabelas simples com unidade e período.","Distinguir observação, interpretação e opinião."],"key_concepts":["Cadeias conectam etapas, agentes e fluxos de recursos, bens e informações.","Indicadores econômicos e socioambientais medem dimensões diferentes.","Escala, denominador e distribuição mudam a interpretação de um valor.","Correlação, causa e associação são afirmações diferentes.","Avaliações responsáveis registram fontes, lacunas, critérios e incerteza."],"progression":[{"stage":"FOUNDATION","focus":"Reconhecer etapas, agentes e a diferença entre total e taxa.","questionIds":["v5-hum-impact-probe-01","v5-hum-impact-probe-02","v5-hum-impact-practice-01"]},{"stage":"APPLICATION","focus":"Ler indicadores com unidade, período e escala e comparar distribuições.","questionIds":["v5-hum-impact-practice-04","v5-hum-impact-practice-08","v5-hum-impact-practice-11"]},{"stage":"TRANSFER","focus":"Avaliar alternativas em cenários novos sem generalizar além das evidências.","questionIds":["v5-hum-impact-transfer-01","v5-hum-impact-transfer-04","v5-hum-impact-transfer-07"]},{"stage":"INTEGRATION","focus":"Integrar escalas, agentes, fontes e limites em uma justificativa.","questionIds":["v5-hum-impact-lock-01","v5-hum-impact-lock-03","v5-hum-impact-lock-05"]},{"stage":"SPACED_REVIEW_CANDIDATE","focus":"Retomar critérios em situações diferentes; agendamento depende de mecanismo separado.","questionIds":["v5-hum-impact-review-01","v5-hum-impact-review-05","v5-hum-impact-review-09"]}],"micro_explanations":[{"trigger":"TOTAL_VS_RATE","text":"Compare o denominador. Um valor por unidade pode cair enquanto o total cresce se a produção aumentar."},{"trigger":"ONE_INDICATOR_JUDGMENT","text":"Um indicador descreve uma dimensão. Procure outros efeitos antes de declarar uma alternativa melhor em tudo."},{"trigger":"CORRELATION_AS_CAUSE","text":"Mudanças simultâneas não provam causa. Confira período, método e outras explicações possíveis."},{"trigger":"SCALE_GENERALIZATION","text":"Uma média regional não descreve cada lugar nem cada grupo. Mostre a escala e as diferenças observadas."}],"remediations":[{"misconception":"RATE_EQUALS_TOTAL","prompt":"Reescreva os dois números com o denominador ao lado. A quantidade total e a taxa contam a mesma coisa?"},{"misconception":"ONE_DIMENSION_DECIDES","prompt":"Liste o indicador que melhorou e o que piorou. Que informação permitiria comparar os dois sem apagar nenhum?"},{"misconception":"CORRELATION_PROVES_CAUSE","prompt":"Que outros fatores mudaram no mesmo período? O dado compara grupos ou apenas observa uma sequência temporal?"},{"misconception":"AVERAGE_DESCRIBES_EVERYONE","prompt":"Quem pode estar acima ou abaixo da média? Que desagregação ou relato situado falta?"},{"misconception":"SOURCE_LABEL_PROVES_TRUTH","prompt":"Qual pergunta a fonte mede, com qual método e período? Que outra fonte poderia conferir o resultado?"}],"review_windows_days":[2,8,21],"review_schedule_status":"PROPOSAL_ONLY_NO_SCHEDULER_WRITE","source_dossier":[{"title":"Base Nacional Comum Curricular: Ensino Médio","publisher":"Ministério da Educação","url":"https://basenacionalcomum.mec.gov.br/images/historico/BNCC_EnsinoMedio_embaixa_site_110518.pdf","accessedOn":"2026-10-13","supports":["The source describes analysis of economic and socio-environmental impacts of production chains across environments and scales, considering local ways of life."],"use":"Used as curricular context for authoring only. This candidate pack does not claim an approved official mapping, and no BNCC skill is registered by this file. No text or question was copied."},{"title":"Contas Econômicas Ambientais da Terra","publisher":"Instituto Brasileiro de Geografia e Estatística (IBGE)","url":"https://www.ibge.gov.br/estatisticas/economicas/contas-nacionais/34822-contas-economicas-ambientais-da-terra.html?lang=pt-BR","accessedOn":"2026-10-13","supports":["Examples of examining land-use change and agricultural establishments through geospatial and economic statistics at regional scales."],"use":"Consulted for the distinction among indicator, scale, and cross-analysis; all numbers in this lesson and its questions are explicitly fictional. No tables or wording were copied."}],"copyright_note":"All lesson prose, examples, questions, distractors, explanations, and activity materials are original. External sources are cited for context and are not reproduced.","authentic_activities":[{"id":"v5-humanities-map-fictional-production-chain","title":"Mapa de uma cadeia fictícia em duas escalas","instructions":"Em grupo, use cartões explicitamente fictícios sobre uma pequena cadeia de alimento: produção, processamento, transporte e venda. Organize etapas e agentes; compare uma tabela de custo e renda por lote com indicadores de água e resíduos por lote; marque o que é local e o que se refere ao conjunto do cenário. Produza duas alternativas, explique quem pode ser afetado em cada uma e anote os dados ausentes antes de recomendar. Não use nomes de comunidades, empresas ou propriedades reais nem apresente os cartões como pesquisa de campo.","evidence":"Diagrama de etapas e agentes, tabela com unidades e escalas preservadas, comparação de pelo menos dois indicadores, nota de incertezas e justificativa de uma alternativa.","privacyGuard":"Usar apenas dados inventados e identificados como simulação. Não coletar relatos, localização ou dados de produtores reais. Não atribuir efeitos a povos ou comunidades reais sem fonte situada, autorização e mediação docente.","rubric":[{"criterion":"Representação da cadeia","emerging":"Lista um produto sem distinguir etapas ou agentes.","developing":"Organiza etapas principais com apoio, mas omite relações ou agentes.","proficient":"Representa etapas e agentes e explica ao menos uma relação entre eles."},{"criterion":"Leitura de indicadores","emerging":"Compara números sem unidade ou período.","developing":"Registra parte das unidades, mas mistura total, taxa ou escala.","proficient":"Compara dimensões diferentes mantendo unidades, períodos, denominadores e escalas."},{"criterion":"Distribuição e evidência","emerging":"Afirma que todos ganham ou perdem sem indicar dados.","developing":"Identifica possíveis grupos, mas não distingue dado de hipótese.","proficient":"Relaciona grupos e efeitos a evidências e declara o que permanece incerto."},{"criterion":"Avaliação de alternativa","emerging":"Escolhe solução única sem critério.","developing":"Aponta um benefício e uma limitação com apoio.","proficient":"Compara alternativas por critérios explícitos e propõe dados para verificar efeitos."}]}],"objective":"Mapear etapas e agentes de uma cadeia produtiva, comparar evidências econômicas e socioambientais em escalas diferentes e justificar conclusões que explicitem limites e alternativas.","common_mistake":"Tratar uma média ou um indicador único como retrato de toda a cadeia, confundir valor por unidade com total, ou atribuir causa e experiência a grupos sem evidência.","estimated_minutes":24}'::jsonb
  ) on conflict (canonical_skill_id, version) do nothing;
  select id into v_lesson_id from public.learning_skill_lessons
   where canonical_skill_id = v_skill_id and version = 5
