  for v_question in
    select * from jsonb_to_recordset('[{"id":"v5-hum-impact-probe-01","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"MAP","contextFamily":"MEL_CADEIA","statement":"Num exercício, a turma estuda um pote de mel fictício. Qual sequência representa etapas possíveis da cadeia antes da compra?","options":["Produção, processamento e embalagem, transporte e venda.","Venda, descarte, extração e só então produção.","Apenas a compra, pois as etapas anteriores não fazem parte da cadeia.","Somente o rótulo e a propaganda."],"correctAnswer":"Produção, processamento e embalagem, transporte e venda.","explanation":"Uma cadeia conecta etapas antes e depois da produção; a sequência exata depende do produto e das fontes usadas.","hint":"Pense no caminho entre obter ou produzir o bem e disponibilizá-lo para compra.","errorFocus":"CHAIN_STAGES_OMITTED","misconceptions":{"Venda, descarte, extração e só então produção.":["CHAIN_ORDER_CONFUSION"],"Apenas a compra, pois as etapas anteriores não fazem parte da cadeia.":["CHAIN_REDUCED_TO_CONSUMPTION"],"Somente o rótulo e a propaganda.":["CHAIN_REDUCED_TO_MARKETING"]},"position":1},{"id":"v5-hum-impact-probe-02","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"COMPARE","contextFamily":"OFICINAS_BENEFICIOS","statement":"Uma tabela fictícia mostra renda média de fornecedores e resíduos gerados por uma oficina. Para avaliar a cadeia, qual pergunta ajuda a observar distribuição?","options":["Qual número é maior, sem olhar quem foi contado?","Quais agentes recebem renda e quais etapas geram resíduos, segundo os dados disponíveis?","Qual produto parece mais bonito?","A média prova que todos os fornecedores recebem o mesmo valor."],"correctAnswer":"Quais agentes recebem renda e quais etapas geram resíduos, segundo os dados disponíveis?","explanation":"Distribuição exige identificar agentes e relacioná-los aos dados; uma média não descreve automaticamente cada pessoa.","hint":"Procure uma pergunta que conecte quem participa a uma evidência específica.","errorFocus":"DISTRIBUTION_NOT_ANALYZED","misconceptions":{"Qual número é maior, sem olhar quem foi contado?":["AGGREGATE_WITHOUT_GROUPS"],"Qual produto parece mais bonito?":["AESTHETIC_REPLACES_EVIDENCE"],"A média prova que todos os fornecedores recebem o mesmo valor.":["AVERAGE_EQUALS_EVERY_PERSON"]},"position":2},{"id":"v5-hum-impact-probe-03","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"IDENTIFY","contextFamily":"TAXA_E_TOTAL","statement":"No cenário fictício, o uso de água por caixa caiu de 5 para 4 litros, mas foram produzidas mais caixas. O que ainda falta para saber o uso total?","options":["Somar o preço de venda de cada caixa.","Saber apenas o nome da empresa.","Conhecer a quantidade total de caixas produzidas em cada período.","Concluir que o total caiu porque o indicador por caixa caiu."],"correctAnswer":"Conhecer a quantidade total de caixas produzidas em cada período.","explanation":"A taxa por caixa não determina o total sem a quantidade produzida em cada período.","hint":"Multiplique o indicador por unidade pela quantidade de unidades.","errorFocus":"RATE_AS_TOTAL","misconceptions":{"Somar o preço de venda de cada caixa.":["WRONG_DIMENSION"],"Saber apenas o nome da empresa.":["SOURCE_LABEL_WITHOUT_MEASURE"],"Concluir que o total caiu porque o indicador por caixa caiu.":["RATE_EQUALS_TOTAL"]},"position":3},{"id":"v5-hum-impact-practice-01","purpose":"PRACTICE","difficulty":"EASY","cognitiveProcess":"CLASSIFY","contextFamily":"SEMENTES_ETAPAS","statement":"Uma cadeia fictícia inclui cultivo de sementes, beneficiamento, transporte e venda. Qual registro identifica corretamente uma etapa e um agente?","options":["O clima é um agente que recebe salário na cadeia.","O preço é uma etapa física entre transporte e loja.","A venda elimina todas as etapas anteriores.","Beneficiamento realizado por uma unidade de processamento."],"correctAnswer":"Beneficiamento realizado por uma unidade de processamento.","explanation":"Beneficiamento é uma etapa; a unidade que o realiza é um agente organizacional da cadeia.","hint":"Separe uma ação ou fase de quem participa dela.","errorFocus":"STAGE_AGENT_CONFUSION","misconceptions":{"O clima é um agente que recebe salário na cadeia.":["CONTEXT_AS_AGENT"],"O preço é uma etapa física entre transporte e loja.":["INDICATOR_AS_STAGE"],"A venda elimina todas as etapas anteriores.":["CHAIN_ERASURE"]},"position":1},{"id":"v5-hum-impact-practice-02","purpose":"PRACTICE","difficulty":"EASY","cognitiveProcess":"COMPARE","contextFamily":"COST_PER_LOTE","statement":"Dois processos fictícios custam R$ 40 por lote de 10 caixas e R$ 54 por lote de 15 caixas. Qual comparação é válida?","options":["O primeiro custa R$ 4 por caixa e o segundo R$ 3,60 por caixa.","O segundo custa mais por caixa porque o valor total é maior.","Os dois custam o mesmo por caixa, pois ambos são lotes.","Não há como calcular custo por caixa mesmo sabendo tamanhos e valores."],"correctAnswer":"O primeiro custa R$ 4 por caixa e o segundo R$ 3,60 por caixa.","explanation":"Dividindo cada custo total pela quantidade, comparamos custo por caixa: 40/10 e 54/15.","hint":"Calcule o custo unitário para cada lote antes de comparar.","errorFocus":"TOTAL_NOT_NORMALIZED","misconceptions":{"O segundo custa mais por caixa porque o valor total é maior.":["TOTAL_AS_UNIT_RATE"],"Os dois custam o mesmo por caixa, pois ambos são lotes.":["UNITS_IGNORED"],"Não há como calcular custo por caixa mesmo sabendo tamanhos e valores.":["KNOWN_DENOMINATOR_IGNORED"]},"position":2},{"id":"v5-hum-impact-practice-03","purpose":"PRACTICE","difficulty":"EASY","cognitiveProcess":"IDENTIFY","contextFamily":"TABELA_SEM_PERIODO","statement":"Um cartão fictício informa “resíduos: 18 toneladas” e não apresenta período. Qual detalhe impede uma comparação temporal segura?","options":["A cor do cartão.","A falta do período a que as 18 toneladas se referem.","O fato de haver um número inteiro.","O título da cadeia, mesmo que esteja claro."],"correctAnswer":"A falta do período a que as 18 toneladas se referem.","explanation":"Sem período, não sabemos se o total corresponde a um dia, mês ou ano e a comparação pode ser enganosa.","hint":"Procure a informação que dá sentido temporal ao total.","errorFocus":"TIMEFRAME_MISSING","misconceptions":{"A cor do cartão.":["PRESENTATION_OVER_MEASURE"],"O fato de haver um número inteiro.":["NUMBER_FORMAT_AS_LIMIT"],"O título da cadeia, mesmo que esteja claro.":["TOPIC_AS_MEASUREMENT_METADATA"]},"position":3},{"id":"v5-hum-impact-practice-04","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"COMPARE","contextFamily":"AGUA_POR_UNIDADE","statement":"Num cenário inventado, o uso de água por tonelada foi 20 unidades na região Norte e 16 na região Sul. A produção total de cada região não foi informada. O que se pode afirmar?","options":["O total de água da região Norte foi necessariamente maior.","A região Sul não usou água para produzir.","O indicador por tonelada é maior no Norte, mas o total não pode ser comparado sem a produção.","A taxa menor prova que todos os impactos da região Sul também são menores."],"correctAnswer":"O indicador por tonelada é maior no Norte, mas o total não pode ser comparado sem a produção.","explanation":"Os números com denominador permitem comparar a taxa. O total depende também do volume produzido.","hint":"Mantenha separados o indicador por unidade e o total regional.","errorFocus":"UNIT_RATE_TO_REGIONAL_TOTAL","misconceptions":{"O total de água da região Norte foi necessariamente maior.":["RATE_EQUALS_TOTAL"],"A região Sul não usou água para produzir.":["LOWER_RATE_EQUALS_ZERO"],"A taxa menor prova que todos os impactos da região Sul também são menores.":["SINGLE_INDICATOR_GENERALIZATION"]},"position":4},{"id":"v5-hum-impact-practice-05","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"CLASSIFY","contextFamily":"INDICADORES_DISTINTOS","statement":"Uma equipe acompanha renda por fornecedor, consumo de água por lote e horas de trabalho por semana. Como organizar esses indicadores?","options":["Todos medem a mesma dimensão porque estão numa única cadeia.","Água mede apenas preço e horas medem quantidade produzida.","Horas de trabalho provam, sozinhas, que a renda foi distribuída igualmente.","Renda é econômica; água e horas de trabalho são dimensões distintas que pedem interpretação própria."],"correctAnswer":"Renda é econômica; água e horas de trabalho são dimensões distintas que pedem interpretação própria.","explanation":"Indicadores representam dimensões diferentes. Eles não devem ser combinados sem definir unidade, significado e critério.","hint":"Pergunte qual aspecto cada medida pretende descrever.","errorFocus":"INDICATORS_COLLAPSED","misconceptions":{"Todos medem a mesma dimensão porque estão numa única cadeia.":["COMMON_CONTEXT_EQUALS_COMMON_MEASURE"],"Água mede apenas preço e horas medem quantidade produzida.":["INDICATOR_MISCLASSIFICATION"],"Horas de trabalho provam, sozinhas, que a renda foi distribuída igualmente.":["WORK_HOURS_AS_INCOME_DISTRIBUTION"]},"position":5},{"id":"v5-hum-impact-practice-06","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"EVALUATE_SOURCE","contextFamily":"RELATORIO_SEM_METODO","statement":"Um relatório fictício diz que uma mudança “reduziu muito o impacto”, mas não informa medida, período ou método. Qual é a resposta mais cuidadosa?","options":["Tratar a afirmação como não verificada e procurar medida, método, período e comparação.","Aceitar a frase porque foi publicada num relatório.","Rejeitar qualquer dado produzido por uma organização.","Converter “muito” em uma porcentagem escolhida pela turma."],"correctAnswer":"Tratar a afirmação como não verificada e procurar medida, método, período e comparação.","explanation":"A autoria importa, mas a afirmação precisa de definição operacional, método e referência para ser avaliada.","hint":"Que informação transformaria uma expressão vaga em uma afirmação examinável?","errorFocus":"SOURCE_CLAIM_WITHOUT_METHOD","misconceptions":{"Aceitar a frase porque foi publicada num relatório.":["SOURCE_LABEL_PROVES_TRUTH"],"Rejeitar qualquer dado produzido por uma organização.":["SOURCE_LABEL_PROVES_FALSEHOOD"],"Converter “muito” em uma porcentagem escolhida pela turma.":["UNSUPPORTED_QUANTIFICATION"]},"position":6},{"id":"v5-hum-impact-practice-07","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"ANALYZE_DISTRIBUTION","contextFamily":"RENDA_MEDIA_E_VARIACAO","statement":"Uma tabela inventada mostra renda média de R$ 900 entre oito fornecedores, sem valores individuais. O que a média permite concluir?","options":["Cada fornecedor recebeu exatamente R$ 900.","A média é R$ 900, mas a distribuição individual não pode ser reconstruída sem outros dados.","O fornecedor de menor renda recebeu zero.","Todos os fornecedores tiveram condições de trabalho iguais."],"correctAnswer":"A média é R$ 900, mas a distribuição individual não pode ser reconstruída sem outros dados.","explanation":"A média resume um conjunto, mas valores muito diferentes podem produzir a mesma média.","hint":"O que uma média resume e que detalhe ela não mostra?","errorFocus":"AVERAGE_AS_UNIFORM_DISTRIBUTION","misconceptions":{"Cada fornecedor recebeu exatamente R$ 900.":["AVERAGE_EQUALS_EVERY_PERSON"],"O fornecedor de menor renda recebeu zero.":["UNSUPPORTED_INDIVIDUAL_VALUE"],"Todos os fornecedores tiveram condições de trabalho iguais.":["INCOME_MEAN_AS_WORK_CONDITIONS"]},"position":7},{"id":"v5-hum-impact-practice-08","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"COMPARE_SCALE","contextFamily":"DADO_LOCAL_E_REGIONAL","statement":"Um estudo fictício mede ruído perto de uma unidade de processamento e outro calcula uma média regional. Por que os resultados não são intercambiáveis?","options":["Porque qualquer média regional é necessariamente falsa.","Porque o local é sempre a escala mais importante.","Porque medem espaços e populações diferentes; a comparação exige método e escala compatíveis.","Porque um número só vale quando todos os moradores participam."],"correctAnswer":"Porque medem espaços e populações diferentes; a comparação exige método e escala compatíveis.","explanation":"Um ponto próximo à unidade e uma média regional respondem perguntas distintas e não descrevem as mesmas pessoas ou áreas.","hint":"Compare o espaço coberto e quem entrou em cada medida.","errorFocus":"SCALES_AS_INTERCHANGEABLE","misconceptions":{"Porque qualquer média regional é necessariamente falsa.":["AGGREGATE_ALWAYS_INVALID"],"Porque o local é sempre a escala mais importante.":["SCALE_HIERARCHY_WITHOUT_QUESTION"],"Porque um número só vale quando todos os moradores participam.":["CENSUS_REQUIRED_FOR_EVERY_MEASURE"]},"position":8},{"id":"v5-hum-impact-practice-09","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"EVALUATE_CAUSALITY","contextFamily":"PRODUCAO_E_RENDA","statement":"Num município fictício, a produção e a renda média cresceram no mesmo ano em que um novo transporte entrou em operação. Qual conclusão os dados apresentados sustentam?","options":["O transporte causou sozinho o aumento da renda.","O transporte não teve nenhuma relação possível.","Toda família do município teve aumento de renda.","A produção e a renda cresceram no período; os dados não isolam a causa."],"correctAnswer":"A produção e a renda cresceram no período; os dados não isolam a causa.","explanation":"A coincidência temporal mostra associação observada, mas não controla outras mudanças nem identifica causalidade.","hint":"O que foi observado diretamente e o que exigiria uma comparação adicional?","errorFocus":"CORRELATION_AS_CAUSE","misconceptions":{"O transporte causou sozinho o aumento da renda.":["SINGLE_CAUSE_ASSUMED"],"O transporte não teve nenhuma relação possível.":["CORRELATION_DISMISSED_AS_NO_RELATION"],"Toda família do município teve aumento de renda.":["MEAN_GENERALIZED_TO_ALL"]},"position":9},{"id":"v5-hum-impact-practice-10","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"EVALUATE_ALTERNATIVE","contextFamily":"EMBALAGEM_TROCA","statement":"Dois protótipos fictícios: A reduz resíduo, mas aumenta custo; B custa menos, mas usa mais material. Que decisão está mais bem justificada?","options":["Definir critérios e grupos afetados, conferir unidades e comparar os efeitos antes de recomendar.","Escolher A sem considerar quem paga o custo.","Escolher B porque preço é o único indicador objetivo.","Declarar que ambos são iguais sem analisar medidas."],"correctAnswer":"Definir critérios e grupos afetados, conferir unidades e comparar os efeitos antes de recomendar.","explanation":"A avaliação precisa explicitar prioridades e distribuição dos efeitos; não há um indicador único que resolva a escolha.","hint":"Que critérios e informações devem aparecer para que a escolha seja transparente?","errorFocus":"SINGLE_CRITERION_DECISION","misconceptions":{"Escolher A sem considerar quem paga o custo.":["BENEFIT_WITHOUT_DISTRIBUTION"],"Escolher B porque preço é o único indicador objetivo.":["PRICE_AS_ONLY_CRITERION"],"Declarar que ambos são iguais sem analisar medidas.":["TRADEOFFS_AS_EQUALITY"]},"position":10},{"id":"v5-hum-impact-practice-11","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"IDENTIFY_GAP","contextFamily":"TRABALHO_CONDICOES","statement":"Um conjunto fictício informa quantidade de empregos e renda total, mas não descreve jornada, segurança ou estabilidade. Qual lacuna deve ser registrada?","options":["Todos os empregos são seguros, pois foram contados.","As condições e a distribuição dos postos de trabalho ainda não foram medidas.","A renda total prova que não há desigualdade.","A cadeia não gera trabalho porque faltam detalhes."],"correctAnswer":"As condições e a distribuição dos postos de trabalho ainda não foram medidas.","explanation":"Contar empregos e renda não responde, por si só, sobre jornada, segurança, estabilidade ou quem ocupa cada função.","hint":"Mantenha a conclusão dentro do que os indicadores medem.","errorFocus":"EMPLOYMENT_COUNT_AS_JOB_QUALITY","misconceptions":{"Todos os empregos são seguros, pois foram contados.":["COUNT_AS_QUALITY"],"A renda total prova que não há desigualdade.":["TOTAL_INCOME_AS_EQUALITY"],"A cadeia não gera trabalho porque faltam detalhes.":["MISSING_DATA_AS_ZERO"]},"position":11},{"id":"v5-hum-impact-transfer-01","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"ANALYZE_SCALE","contextFamily":"FRUTA_TRANSPORTE_FICTICIO","statement":"Uma turma inventa uma cadeia de fruta: o transporte refrigerado reduz perdas no trajeto, mas usa energia. Qual comparação ajudaria a avaliar a mudança sem presumir o resultado?","options":["Contar apenas a fruta que chegou e chamar o processo sustentável.","Ignorar perdas porque não são um impacto.","Comparar perdas, energia e período para volumes equivalentes, indicando limites dos dados.","Supor que qualquer refrigeração aumenta o impacto em toda situação."],"correctAnswer":"Comparar perdas, energia e período para volumes equivalentes, indicando limites dos dados.","explanation":"A comparação precisa manter volumes e períodos comparáveis e observar mais de uma dimensão.","hint":"Quais medidas podem melhorar e piorar ao mesmo tempo?","errorFocus":"TRADEOFF_NOT_COMPARED","misconceptions":{"Contar apenas a fruta que chegou e chamar o processo sustentável.":["SINGLE_BENEFIT_AS_TOTAL_JUDGMENT"],"Ignorar perdas porque não são um impacto.":["LOST_PRODUCT_OMITTED"],"Supor que qualquer refrigeração aumenta o impacto em toda situação.":["TECHNOLOGY_EFFECT_ASSUMED"]},"position":1},{"id":"v5-hum-impact-transfer-02","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"COMPARE_GROUPS","contextFamily":"COOPERATIVA_FORNECEDORES","statement":"Numa simulação, a renda média de uma cooperativa subiu, mas o número de participantes também mudou. Qual checagem evita uma conclusão apressada?","options":["Afirmar que cada participante passou a ganhar mais.","Usar apenas a renda total mais recente.","Descartar a comparação porque a amostra mudou.","Comparar dados por participante e composição dos grupos nos dois períodos."],"correctAnswer":"Comparar dados por participante e composição dos grupos nos dois períodos.","explanation":"A composição diferente pode alterar a média; é preciso comparar denominadores e grupos equivalentes quando possível.","hint":"Quem está incluído em cada média e qual é o denominador?","errorFocus":"COMPOSITION_CHANGE_IGNORED","misconceptions":{"Afirmar que cada participante passou a ganhar mais.":["MEAN_CHANGE_AS_INDIVIDUAL_GAIN"],"Usar apenas a renda total mais recente.":["ONE_PERIOD_ONLY"],"Descartar a comparação porque a amostra mudou.":["COMPARISON_IMPOSSIBLE_WITH_LIMITATION"]},"position":2},{"id":"v5-hum-impact-transfer-03","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"EVALUATE_SOURCE","contextFamily":"MAPA_DE_USO","statement":"Um mapa fictício mostra mudança de uso do solo em uma região ampla, mas não identifica famílias ou práticas locais. O que deve acompanhar seu uso?","options":["A indicação da escala e a busca de fontes situadas para entender experiências locais.","A afirmação de que todas as famílias fizeram a mesma mudança.","Uma explicação de que o mapa prova a causa de cada alteração.","A substituição por uma opinião sem referência."],"correctAnswer":"A indicação da escala e a busca de fontes situadas para entender experiências locais.","explanation":"Mapas regionais ajudam a observar padrões, mas não substituem evidências locais nem explicam sozinhos as causas.","hint":"O que a escala cartográfica consegue mostrar e o que ela deixa fora?","errorFocus":"REGIONAL_MAP_AS_LOCAL_TESTIMONY","misconceptions":{"A afirmação de que todas as famílias fizeram a mesma mudança.":["GROUP_HOMOGENIZATION"],"Uma explicação de que o mapa prova a causa de cada alteração.":["MAP_AS_CAUSAL_PROOF"],"A substituição por uma opinião sem referência.":["EVIDENCE_REPLACED_BY_OPINION"]},"position":3},{"id":"v5-hum-impact-transfer-04","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"EVALUATE_ALTERNATIVE","contextFamily":"REUSO_AGUA","statement":"Um processo fictício reutiliza água e reduz captação por lote, mas requer manutenção que nem todos os fornecedores conseguem custear. Qual análise amplia a avaliação?","options":["Chamar a alternativa de igualmente acessível porque a taxa caiu.","Comparar economia de água, custos, acesso à manutenção e distribuição dos benefícios.","Avaliar apenas o preço do produto final.","Presumir que fornecedores que não adotaram a mudança não se importam com o ambiente."],"correctAnswer":"Comparar economia de água, custos, acesso à manutenção e distribuição dos benefícios.","explanation":"Uma medida pode reduzir uso e criar barreiras de adoção; avaliação inclui efeitos e acesso entre agentes.","hint":"Quem consegue adotar a mudança e quem recebe o benefício?","errorFocus":"TECHNICAL_GAIN_WITHOUT_ACCESS","misconceptions":{"Chamar a alternativa de igualmente acessível porque a taxa caiu.":["EFFICIENCY_AS_EQUAL_ACCESS"],"Avaliar apenas o preço do produto final.":["COST_ONLY"],"Presumir que fornecedores que não adotaram a mudança não se importam com o ambiente.":["MOTIVE_INFERENCE_WITHOUT_EVIDENCE"]},"position":4},{"id":"v5-hum-impact-transfer-05","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"DISTINGUISH_CAUSE","contextFamily":"SECA_E_PRODUCAO","statement":"Num caso inventado, a produção cai durante uma estiagem e o custo de transporte sobe no mesmo ano. Que evidência ajudaria a separar fatores?","options":["A opinião de uma pessoa escolhida depois de ver o resultado.","Somente o valor final da produção.","Uma comparação de períodos e locais com medidas de chuva, produção e transporte, além de outras mudanças relevantes.","A certeza de que a estiagem explica todas as mudanças."],"correctAnswer":"Uma comparação de períodos e locais com medidas de chuva, produção e transporte, além de outras mudanças relevantes.","explanation":"Vários fatores coincidem; dados comparáveis ajudam a avaliar contribuições sem garantir uma causa única.","hint":"Como comparar situações para observar fatores que mudaram separadamente?","errorFocus":"MULTIPLE_CAUSES_COLLAPSED","misconceptions":{"A opinião de uma pessoa escolhida depois de ver o resultado.":["ANECDOTE_AS_CAUSAL_TEST"],"Somente o valor final da produção.":["OUTCOME_WITHOUT_EXPLANATORY_VARIABLES"],"A certeza de que a estiagem explica todas as mudanças.":["SINGLE_CAUSE_ASSUMED"]},"position":5},{"id":"v5-hum-impact-transfer-06","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"ANALYZE_DISTRIBUTION","contextFamily":"BENEFICIO_E_CUSTO","statement":"Uma simulação de nova rota reduz o custo médio de transporte, mas desloca o trajeto para perto de poucas moradias. Que questão precisa entrar na análise?","options":["A média prova que todas as pessoas foram beneficiadas.","Se o custo caiu, efeitos sobre moradias deixam de importar.","A população deve ser descrita como homogênea.","Quantas moradias podem ser afetadas, quais medidas locais existem e quem participa da decisão."],"correctAnswer":"Quantas moradias podem ser afetadas, quais medidas locais existem e quem participa da decisão.","explanation":"Média econômica e efeito localizado têm escalas e grupos distintos; a distribuição e a participação precisam ser examinadas.","hint":"Uma média de custo mostra o que acontece perto do novo trajeto?","errorFocus":"AVERAGE_HIDES_LOCALIZED_COST","misconceptions":{"A média prova que todas as pessoas foram beneficiadas.":["AVERAGE_EQUALS_EVERY_PERSON"],"Se o custo caiu, efeitos sobre moradias deixam de importar.":["ECONOMIC_BENEFIT_ERASES_SOCIAL_COST"],"A população deve ser descrita como homogênea.":["GROUP_HOMOGENIZATION"]},"position":6},{"id":"v5-hum-impact-transfer-07","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"JUSTIFY","contextFamily":"ROTULO_DE_ORIGEM","statement":"Uma etiqueta fictícia afirma que um produto é “responsável”, sem informar critérios, verificação ou período. Qual pedido de evidência é mais útil?","options":["Quem definiu os critérios, como foram verificados e a quais etapas e período se aplicam?","Qual cor da etiqueta transmite mais confiança?","A afirmação deve ser aceita porque usa uma palavra positiva.","A etiqueta prova que não existe nenhum impacto."],"correctAnswer":"Quem definiu os critérios, como foram verificados e a quais etapas e período se aplicam?","explanation":"Termos gerais precisam de critérios e escopo verificáveis; nenhum rótulo prova ausência total de impacto.","hint":"Transforme a palavra abrangente em perguntas verificáveis.","errorFocus":"LABEL_WITHOUT_CRITERIA","misconceptions":{"Qual cor da etiqueta transmite mais confiança?":["DESIGN_AS_EVIDENCE"],"A afirmação deve ser aceita porque usa uma palavra positiva.":["POSITIVE_LABEL_AS_PROOF"],"A etiqueta prova que não existe nenhum impacto.":["ZERO_IMPACT_CLAIM"]},"position":7},{"id":"v5-hum-impact-lock-01","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"CALCULATE_AND_COMPARE","contextFamily":"TAXA_CRESCE_ESCALA","statement":"Cenário fictício: água por lote cai de 10 para 8 unidades; a produção aumenta de 100 para 140 lotes. Qual conclusão numérica está correta?","options":["O total novo é 800 unidades e caiu.","O total passou de 1.000 para 1.120 unidades, apesar da redução por lote.","O total antigo e o novo são iguais.","O total não pode ser calculado com esses dados."],"correctAnswer":"O total passou de 1.000 para 1.120 unidades, apesar da redução por lote.","explanation":"10 × 100 = 1.000 e 8 × 140 = 1.120. A taxa caiu, mas o total aumentou com a escala.","hint":"Multiplique cada taxa pela quantidade de lotes do mesmo período.","errorFocus":"EFFICIENCY_REBOUND_IGNORED","misconceptions":{"O total novo é 800 unidades e caiu.":["RATE_TIMES_WRONG_BASE"],"O total antigo e o novo são iguais.":["ARITHMETIC_OR_SCALE_IGNORED"],"O total não pode ser calculado com esses dados.":["KNOWN_TOTAL_INPUTS_IGNORED"]},"position":1},{"id":"v5-hum-impact-lock-02","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"EVALUATE_EVIDENCE","contextFamily":"PESQUISA_SEM_BASELINE","statement":"Uma equipe afirma que um novo processo reduziu resíduos, mas apresenta somente uma medição feita depois da mudança. O que falta para sustentar a comparação?","options":["Uma frase de divulgação mais convincente.","A conclusão de que o processo não funciona.","Uma referência comparável anterior ou grupo de comparação, com método e período descritos.","A soma de resíduos de produtos sem relação."],"correctAnswer":"Uma referência comparável anterior ou grupo de comparação, com método e período descritos.","explanation":"Sem referência comparável não se mede a mudança atribuída ao processo; outras condições também podem ter variado.","hint":"Uma redução é uma diferença entre que medidas?","errorFocus":"NO_BASELINE","misconceptions":{"Uma frase de divulgação mais convincente.":["RHETORIC_AS_EVIDENCE"],"A conclusão de que o processo não funciona.":["MISSING_EVIDENCE_AS_NEGATIVE_RESULT"],"A soma de resíduos de produtos sem relação.":["INCOMPARABLE_MEASURES"]},"position":2},{"id":"v5-hum-impact-lock-03","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"ANALYZE_SCALE","contextFamily":"MEDIA_REGIONAL_E_GRUPOS","statement":"Numa tabela inventada, o emprego médio aumenta na região, enquanto dois municípios têm resultados diferentes. Qual relato preserva a evidência?","options":["Todos os municípios tiveram o mesmo aumento.","A média regional torna os resultados municipais irrelevantes.","O município com queda prova que a média regional está errada.","Os dados mostram aumento médio e variação entre municípios; causas e experiências locais exigem análise adicional."],"correctAnswer":"Os dados mostram aumento médio e variação entre municípios; causas e experiências locais exigem análise adicional.","explanation":"A média e os valores locais coexistem, mas respondem perguntas diferentes; nenhum apaga o outro.","hint":"Como mencionar o padrão agregado sem esconder a variação?","errorFocus":"AGGREGATE_LOCAL_CONFLICT","misconceptions":{"Todos os municípios tiveram o mesmo aumento.":["MEAN_AS_UNIFORMITY"],"A média regional torna os resultados municipais irrelevantes.":["AGGREGATE_ERASES_LOCAL"],"O município com queda prova que a média regional está errada.":["LOCAL_OUTLIER_INVALIDATES_AGGREGATE"]},"position":3},{"id":"v5-hum-impact-lock-04","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"EVALUATE_ALTERNATIVES","contextFamily":"RECICLAGEM_E_TRANSPORTE","statement":"Duas opções fictícias: uma usa menos material novo e percorre maior distância; outra percorre menos distância e gera mais descarte. Qual plano de avaliação é mais completo?","options":["Definir unidades funcionais e comparar material, transporte e descarte no mesmo período.","Escolher a distância menor sem olhar os outros efeitos.","Escolher a menor quantidade de material sem considerar a cadeia.","Somar quilômetro, quilo e custo como se fossem uma unidade."],"correctAnswer":"Definir unidades funcionais e comparar material, transporte e descarte no mesmo período.","explanation":"Uma comparação precisa usar uma base equivalente e manter as dimensões separadas ou justificar como serão ponderadas.","hint":"Compare a mesma função entregue antes de comparar opções.","errorFocus":"ALTERNATIVE_FUNCTION_NOT_NORMALIZED","misconceptions":{"Escolher a distância menor sem olhar os outros efeitos.":["SINGLE_INDICATOR_DECIDES"],"Escolher a menor quantidade de material sem considerar a cadeia.":["BOUNDARY_TOO_NARROW"],"Somar quilômetro, quilo e custo como se fossem uma unidade.":["INCOMMENSURATE_INDICATORS_ADDED"]},"position":4},{"id":"v5-hum-impact-lock-05","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"JUSTIFY_WITH_LIMITS","contextFamily":"RELATO_DADO_E_LACUNA","statement":"Uma fonte fictícia informa que 30 de 50 unidades consultadas adotaram uma prática, mas não explica como foram escolhidas. Qual frase é mais rigorosa?","options":["A prática é usada por 60% de todas as unidades do país.","Na amostra descrita, 30 de 50 adotaram; sem método de seleção, não se pode generalizar para todas.","Nenhuma unidade adotou a prática.","O dado não pode ser mencionado porque não representa todo o país."],"correctAnswer":"Na amostra descrita, 30 de 50 adotaram; sem método de seleção, não se pode generalizar para todas.","explanation":"A proporção na amostra é 60%, mas representatividade depende de como as unidades foram selecionadas.","hint":"Restrinja a frase ao conjunto efetivamente observado.","errorFocus":"SAMPLE_GENERALIZED_TO_POPULATION","misconceptions":{"A prática é usada por 60% de todas as unidades do país.":["SAMPLE_AS_POPULATION"],"Nenhuma unidade adotou a prática.":["SAMPLE_RESULT_REVERSED"],"O dado não pode ser mencionado porque não representa todo o país.":["LIMITATION_ERASES_DESCRIPTIVE_VALUE"]},"position":5},{"id":"v5-hum-impact-review-01","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"COMPARE","contextFamily":"FIBRA_POR_PECA","statement":"Numa simulação, uma peça usa menos fibra por unidade, mas as vendas dobram. Que par de medidas deve ser observado?","options":["Somente o número de lojas.","Apenas a cor da fibra.","Fibra por peça e número de peças, para estimar também o total.","O total de fibra sem dizer período ou quantidade produzida."],"correctAnswer":"Fibra por peça e número de peças, para estimar também o total.","explanation":"A taxa e a escala são necessárias para calcular o total e comparar períodos.","hint":"Quais dois fatores formam o total?","errorFocus":"RATE_AND_SCALE_SEPARATED","misconceptions":{"Somente o número de lojas.":["IRRELEVANT_SCALE"],"Apenas a cor da fibra.":["PRESENTATION_OVER_MEASURE"],"O total de fibra sem dizer período ou quantidade produzida.":["TOTAL_WITHOUT_DENOMINATOR"]},"position":1},{"id":"v5-hum-impact-review-02","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"IDENTIFY","contextFamily":"RELATORIO_DE_PERIODO","statement":"Um relatório fictício compara custos de duas safras, mas usa moeda e método contábil diferentes. O que é necessário antes de comparar?","options":["Ordenar os relatórios pelo tamanho do arquivo.","Assumir que qualquer custo é comparável sem contexto.","Apagar a safra mais antiga.","Ajustar ou explicar as diferenças de moeda, período e método."],"correctAnswer":"Ajustar ou explicar as diferenças de moeda, período e método.","explanation":"Diferenças de unidade e método podem explicar parte do contraste observado.","hint":"Quais metadados definem o que significa cada valor?","errorFocus":"MEASUREMENTS_NOT_COMPARABLE","misconceptions":{"Ordenar os relatórios pelo tamanho do arquivo.":["FILE_SIZE_AS_DATA_QUALITY"],"Assumir que qualquer custo é comparável sem contexto.":["UNITS_AND_METHOD_IGNORED"],"Apagar a safra mais antiga.":["HISTORICAL_CONTEXT_DISCARDED"]},"position":2},{"id":"v5-hum-impact-review-03","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"ANALYZE","contextFamily":"AGENTE_E_ETAPA","statement":"Numa cadeia simulada, trabalhadores transportam material entre uma unidade e a loja. Qual pergunta localiza melhor a participação deles?","options":["Qual etapa realizam, em quais condições descritas e como ela se conecta às outras?","Qual trabalhador representa toda a cadeia?","Por que o transporte é sempre a etapa menos importante?","Como provar que o produto não teve nenhum impacto?"],"correctAnswer":"Qual etapa realizam, em quais condições descritas e como ela se conecta às outras?","explanation":"Identificar tarefa e conexão ajuda a mapear agentes sem generalizar uma pessoa para toda a cadeia.","hint":"Descreva papel e relação antes de avaliar o conjunto.","errorFocus":"INDIVIDUAL_AS_REPRESENTATIVE","misconceptions":{"Qual trabalhador representa toda a cadeia?":["ONE_PERSON_AS_GROUP"],"Por que o transporte é sempre a etapa menos importante?":["UNSUPPORTED_STAGE_HIERARCHY"],"Como provar que o produto não teve nenhum impacto?":["ZERO_IMPACT_PREMISE"]},"position":3},{"id":"v5-hum-impact-review-04","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"EVALUATE_SOURCE","contextFamily":"FONTE_COM_INTERESSE","statement":"Uma empresa publica dados de sua própria cadeia e descreve seu método. Como usar a fonte criticamente?","options":["Aceitar tudo porque a empresa conhece o processo.","Examinar método, escopo e limitações e comparar afirmações relevantes com outras fontes.","Descartar automaticamente porque a empresa tem interesse.","Tratar qualquer número publicado como opinião sem valor."],"correctAnswer":"Examinar método, escopo e limitações e comparar afirmações relevantes com outras fontes.","explanation":"Interesse é contexto relevante, não veredito automático; transparência metodológica e triangulação ajudam a avaliar evidência.","hint":"Evite tanto confiança automática quanto rejeição automática.","errorFocus":"INTEREST_AS_AUTOMATIC_VERDICT","misconceptions":{"Aceitar tudo porque a empresa conhece o processo.":["INTEREST_IGNORED"],"Descartar automaticamente porque a empresa tem interesse.":["INTEREST_AS_AUTOMATIC_FALSEHOOD"],"Tratar qualquer número publicado como opinião sem valor.":["EVIDENCE_AS_OPINION"]},"position":4},{"id":"v5-hum-impact-review-05","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"COMPARE_SCALE","contextFamily":"MEDIA_COM_DESAGREGACAO","statement":"Uma média nacional fictícia de preço aumentou, enquanto algumas regiões registraram queda. Qual relato mantém as duas observações?","options":["O preço subiu em cada região.","O preço caiu em todo o país.","A média nacional subiu, mas houve variação regional; é preciso examinar distribuição e período.","As regiões com queda devem ser excluídas."],"correctAnswer":"A média nacional subiu, mas houve variação regional; é preciso examinar distribuição e período.","explanation":"O agregado pode subir enquanto alguns valores regionais caem; as escalas não se contradizem necessariamente.","hint":"Descreva o agregado e a variação sem substituir um pelo outro.","errorFocus":"AGGREGATE_ERASES_VARIATION","misconceptions":{"O preço subiu em cada região.":["MEAN_AS_UNIFORMITY"],"O preço caiu em todo o país.":["SUBSET_AS_WHOLE"],"As regiões com queda devem ser excluídas.":["UNFAVORABLE_DATA_EXCLUDED"]},"position":5},{"id":"v5-hum-impact-review-06","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"EVALUATE_CAUSALITY","contextFamily":"PROGRAMA_E_INDICADOR","statement":"Após um programa fictício, o consumo de energia caiu. Não há comparação com unidades sem o programa. Qual formulação é mais cuidadosa?","options":["O programa causou a queda em todas as unidades.","O programa não pode ter contribuído.","A queda prova que o método funciona em qualquer setor.","O consumo caiu após o programa; essa sequência não basta para atribuir a mudança exclusivamente a ele."],"correctAnswer":"O consumo caiu após o programa; essa sequência não basta para atribuir a mudança exclusivamente a ele.","explanation":"A ordem temporal é observada, mas outras mudanças podem ter contribuído; a formulação não deve exceder o desenho disponível.","hint":"Diga o que veio depois e o que ainda não foi demonstrado.","errorFocus":"BEFORE_AFTER_AS_CAUSAL_PROOF","misconceptions":{"O programa causou a queda em todas as unidades.":["CAUSATION_WITHOUT_COMPARISON"],"O programa não pode ter contribuído.":["NO_CONTROL_AS_NO_EFFECT"],"A queda prova que o método funciona em qualquer setor.":["LOCAL_RESULT_AS_UNIVERSAL"]},"position":6},{"id":"v5-hum-impact-review-07","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"ANALYZE_DISTRIBUTION","contextFamily":"CUSTO_TRANSFERIDO","statement":"Numa simulação, uma etapa reduz seu próprio gasto ao transferir o descarte para outra empresa. Que aspecto deve ser verificado?","options":["Se o custo desapareceu ou apenas mudou de agente e etapa.","Se o primeiro agente deixou de aparecer no diagrama.","Se o gasto interno caiu, então o impacto total necessariamente caiu.","Se a empresa que recebe o descarte não participa da cadeia."],"correctAnswer":"Se o custo desapareceu ou apenas mudou de agente e etapa.","explanation":"A fronteira de análise importa: uma redução para um agente pode deslocar custos a outro, não eliminá-los.","hint":"Siga o fluxo do material e do custo depois da transferência.","errorFocus":"COST_SHIFTED_NOT_REMOVED","misconceptions":{"Se o primeiro agente deixou de aparecer no diagrama.":["ACCOUNTING_BOUNDARY_AS_REAL_CHANGE"],"Se o gasto interno caiu, então o impacto total necessariamente caiu.":["FIRM_LEVEL_AS_CHAIN_LEVEL"],"Se a empresa que recebe o descarte não participa da cadeia.":["OUTSOURCED_STAGE_OMITTED"]},"position":7},{"id":"v5-hum-impact-review-08","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"JUSTIFY_WITH_UNCERTAINTY","contextFamily":"AMOSTRA_PEQUENA","statement":"Uma atividade ouviu quatro participantes voluntários sobre mudanças na cadeia. Qual uso dos relatos é mais adequado?","options":["Calcular com eles a opinião de todas as pessoas da região.","Usá-los como pistas de experiências e indicar que não representam necessariamente todo o grupo.","Descartar os relatos porque quatro nunca informam nada.","Atribuir as mesmas falas a quem não participou."],"correctAnswer":"Usá-los como pistas de experiências e indicar que não representam necessariamente todo o grupo.","explanation":"Relatos podem iluminar experiências, mas amostra pequena e voluntária não autoriza generalização populacional.","hint":"Que tipo de evidência é um relato e qual limite acompanha esse tipo de amostra?","errorFocus":"VOLUNTARY_SAMPLE_GENERALIZATION","misconceptions":{"Calcular com eles a opinião de todas as pessoas da região.":["SMALL_SAMPLE_AS_POPULATION"],"Descartar os relatos porque quatro nunca informam nada.":["QUALITATIVE_EVIDENCE_DISMISSED"],"Atribuir as mesmas falas a quem não participou.":["VOICE_ATTRIBUTION_WITHOUT_CONSENT"]},"position":8},{"id":"v5-hum-impact-review-09","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"SYNTHESIZE","contextFamily":"RECOMENDACAO_COM_LIMITE","statement":"Uma equipe tem dados fictícios de custo, água por lote e distância, mas nenhum dado sobre condições de trabalho. Qual recomendação demonstra melhor síntese?","options":["Declarar que a opção escolhida é sustentável em todas as dimensões.","Escolher o menor custo e ocultar os demais indicadores.","Comparar custo, água e distância com suas unidades, explicitar critérios e registrar que condições de trabalho ainda precisam ser investigadas.","Afirmar que não há dados úteis porque uma dimensão está ausente."],"correctAnswer":"Comparar custo, água e distância com suas unidades, explicitar critérios e registrar que condições de trabalho ainda precisam ser investigadas.","explanation":"Uma síntese útil usa evidências disponíveis, torna os critérios visíveis e identifica lacunas sem prometer uma avaliação completa.","hint":"Inclua o que se sabe e o que ainda não foi medido.","errorFocus":"SYNTHESIS_HIDES_GAPS","misconceptions":{"Declarar que a opção escolhida é sustentável em todas as dimensões.":["PARTIAL_DATA_AS_TOTAL_CERTAINTY"],"Escolher o menor custo e ocultar os demais indicadores.":["SELECTIVE_REPORTING"],"Afirmar que não há dados úteis porque uma dimensão está ausente.":["ONE_GAP_ERASES_ALL_EVIDENCE"]},"position":9}]'::jsonb) as item(
      id text, purpose text, difficulty text, "cognitiveProcess" text,
      "contextFamily" text, statement text, options jsonb, "correctAnswer" text,
      explanation text, hint text, "errorFocus" text, misconceptions jsonb, position integer
    )
  loop
    insert into public.learning_question_sets(scope, canonical_skill_id, purpose, version, active, metadata)
    values ('GLOBAL', v_skill_id, v_question.purpose, 5, false,
      jsonb_build_object('content_pack', 'TECESCOLA_CORE_V5_QUESTION_FIRST', 'content_id', 'v5-humanities-production-impacts',
        'pedagogical_review_status', 'PEDAGOGICAL_REVIEW_PENDING', 'publication_status', 'STAGING',
        'bncc_alignment_status', 'NOT_CLAIMED'))
    on conflict (canonical_skill_id, purpose, version) where scope = 'GLOBAL' do nothing;
    select id into v_set_id from public.learning_question_sets
     where scope = 'GLOBAL' and canonical_skill_id = v_skill_id
       and purpose = v_question.purpose and version = 5
       and metadata->>'content_id' = 'v5-humanities-production-impacts' and active = false;
    if v_set_id is null then raise exception 'V5_CONTENT_QUESTION_SET_CONFLICT'; end if;

    select id into v_question_id from public.learning_question_bank
     where source_type = 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING' and metadata->>'content_id' = v_question.id;
    if v_question_id is null then
      insert into public.learning_question_bank(
        package_type, source_type, source_name, subject_area, domain, topic,
        statement, options, correct_answer, explanation, difficulty,
        estimated_minutes, provenance, metadata, active
      ) values (
        'TECESCOLA', 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING', 'TecEscola Question First V5 - Staging',
        'HUMANITIES', 'IMPACTOS_SOCIOAMBIENTAIS', 'cadeias produtivas escalas evidencias e alternativas',
        v_question.statement, v_question.options, to_jsonb(v_question."correctAnswer"),
        v_question.explanation, v_question.difficulty, 2,
        'TECESCOLA_CORE_V5_AUTHORED',
        jsonb_build_object('content_pack', 'TECESCOLA_CORE_V5_QUESTION_FIRST', 'content_id', v_question.id,
          'purpose', v_question.purpose, 'context_family', v_question."contextFamily",
          'cognitive_process', v_question."cognitiveProcess", 'error_focus', v_question."errorFocus",
          'remediation_hint', v_question.hint, 'misconceptions', v_question.misconceptions,
          'content_authoring_status', 'AUTHORED', 'pedagogical_review_status', 'PEDAGOGICAL_REVIEW_PENDING',
          'publication_status', 'STAGING', 'bncc_alignment_status', 'NOT_CLAIMED'), false
      ) returning id into v_question_id;
    end if;
    if v_question_id is null then raise exception 'V5_CONTENT_QUESTION_INSERT_FAILED'; end if;
    update public.learning_question_bank set active = false
     where id = v_question_id and source_type = 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING';
    insert into public.learning_question_bank_skill_links(question_bank_id, canonical_skill_id, skill_role)
    values (v_question_id, v_skill_id, 'PRIMARY') on conflict (question_bank_id, canonical_skill_id) do nothing;
    insert into public.learning_question_set_items(question_set_id, question_bank_id, position)
    values (v_set_id, v_question_id, v_question.position)
    on conflict (question_set_id, question_bank_id) do nothing;
  end loop;
end;
$seed_question_first_content_v5$;

